import re

with open('lib/core/app_strings.dart', 'r', encoding='utf-8') as f:
    app_strings = f.read()

# First, remove any existing injected block
app_strings = re.sub(
    r"(// AUTO TRANSLATED RECIPE DESCRIPTIONS\n).*?('brew_dose':)",
    r"\1\2",
    app_strings,
    flags=re.DOTALL
)

app_strings = app_strings.replace("      // AUTO TRANSLATED RECIPE DESCRIPTIONS\n", "")

en_additions = "      // AUTO TRANSLATED RECIPE DESCRIPTIONS\n"
for key, val in translations.items():
    safe_key = key.replace('\\n', '\\\\n').replace("'", "\\'")
    safe_val = val.replace('\\n', '\\\\n').replace("'", "\\'")
    en_additions += f"      '{safe_key}': '{safe_val}',\n"

app_strings = re.sub(
    r"('en':\s*\{)",
    r"\1\n" + en_additions,
    app_strings
)

with open('lib/core/app_strings.dart', 'w', encoding='utf-8') as f:
    f.write(app_strings)

print("Injected 130+ manual translations safely!")
